pub static mut MO: [HSD_MObj; 2] = unsafe { core::mem::zeroed() };
pub fn pick_HSD_MObj() -> *mut HSD_MObj { let r = rnd(); unsafe { if r % 6 == 0 { core::ptr::null_mut() } else { &raw mut MO[((r >> 8) % 2) as usize] } } }
pub static mut MA: [HSD_Material; 2] = unsafe { core::mem::zeroed() };
pub fn pick_HSD_Material() -> *mut HSD_Material { let r = rnd(); unsafe { if r % 6 == 0 { core::ptr::null_mut() } else { &raw mut MA[((r >> 8) % 2) as usize] } } }
pub static mut TO: [HSD_TObj; 5] = unsafe { core::mem::zeroed() };
pub fn pick_HSD_TObj() -> *mut HSD_TObj { let r = rnd(); unsafe { if r % 6 == 0 { core::ptr::null_mut() } else { &raw mut TO[((r >> 8) % 5) as usize] } } }
pub static mut DO: [HSD_DObj; 3] = unsafe { core::mem::zeroed() };
pub fn pick_HSD_DObj() -> *mut HSD_DObj { let r = rnd(); unsafe { if r % 6 == 0 { core::ptr::null_mut() } else { &raw mut DO[((r >> 8) % 3) as usize] } } }
pub static mut PE: [HSD_PEDesc; 2] = unsafe { core::mem::zeroed() };
pub fn pick_HSD_PEDesc() -> *mut HSD_PEDesc { let r = rnd(); unsafe { if r % 6 == 0 { core::ptr::null_mut() } else { &raw mut PE[((r >> 8) % 2) as usize] } } }
pub static mut CO: [ColorOverlay; 2] = unsafe { core::mem::zeroed() };
pub fn pick_ColorOverlay() -> *mut ColorOverlay { let r = rnd(); unsafe { if r % 6 == 0 { core::ptr::null_mut() } else { &raw mut CO[((r >> 8) % 2) as usize] } } }
pub static mut MI: [HSD_MObjInfo; 1] = unsafe { core::mem::zeroed() };
pub fn pick_HSD_MObjInfo() -> *mut HSD_MObjInfo { let r = rnd(); unsafe { if r % 6 == 0 { core::ptr::null_mut() } else { &raw mut MI[((r >> 8) % 1) as usize] } } }
pub fn setup_xpools() { unsafe {
    MO = core::mem::zeroed();
    for i in 0..2 { fill_HSD_MObj(&mut MO[i]); }
    MA = core::mem::zeroed();
    for i in 0..2 { fill_HSD_Material(&mut MA[i]); }
    TO = core::mem::zeroed();
    for i in 0..5 { fill_HSD_TObj(&mut TO[i]); }
    DO = core::mem::zeroed();
    for i in 0..3 { fill_HSD_DObj(&mut DO[i]); }
    PE = core::mem::zeroed();
    for i in 0..2 { fill_HSD_PEDesc(&mut PE[i]); }
    CO = core::mem::zeroed();
    for i in 0..2 { fill_ColorOverlay(&mut CO[i]); }
    MI = core::mem::zeroed();
    for i in 0..1 { fill_HSD_MObjInfo(&mut MI[i]); }
} }
pub fn hash_xpools() { unsafe {
    for i in 0..2 { hash_HSD_MObj(&MO[i]); }
    for i in 0..2 { hash_HSD_Material(&MA[i]); }
    for i in 0..5 { hash_HSD_TObj(&TO[i]); }
    for i in 0..3 { hash_HSD_DObj(&DO[i]); }
    for i in 0..2 { hash_HSD_PEDesc(&PE[i]); }
    for i in 0..2 { hash_ColorOverlay(&CO[i]); }
    for i in 0..1 { hash_HSD_MObjInfo(&MI[i]); }
} }
pub fn preg_xpools() { unsafe {
    preg(&raw const MO, core::mem::size_of_val(&MO));
    preg(&raw const MA, core::mem::size_of_val(&MA));
    preg(&raw const TO, core::mem::size_of_val(&TO));
    preg(&raw const DO, core::mem::size_of_val(&DO));
    preg(&raw const PE, core::mem::size_of_val(&PE));
    preg(&raw const CO, core::mem::size_of_val(&CO));
    preg(&raw const MI, core::mem::size_of_val(&MI));
} }

